#ifndef BPR_SRC_ADAPTERS_SQLITE_SRC_PRIVATE_REVIEW_DATABASE_HPP
#define BPR_SRC_ADAPTERS_SQLITE_SRC_PRIVATE_REVIEW_DATABASE_HPP
#include "bpr/application/private_review_store.hpp"
#include "sqlite_connection.hpp"
#include <array>
namespace bpr::adapters::sqlite::detail {
	struct private_schema_table
	{
		std::string_view Name;
		std::string_view Sql;
	};
	inline constexpr std::array PrivateSchemaTables{
		private_schema_table{ "private_composition", "CREATE TABLE private_composition(scope_id INTEGER NOT NULL REFERENCES review_scope(scope_id),id INTEGER NOT NULL CHECK(id>0),version INTEGER NOT NULL CHECK(version>0),record BLOB NOT NULL CHECK(length(record)<=131072),PRIMARY KEY(scope_id,id)) STRICT" },
		private_schema_table{ "private_composition_source", "CREATE TABLE private_composition_source(scope_id INTEGER NOT NULL,composition_id INTEGER NOT NULL,position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 255),source_id INTEGER NOT NULL,PRIMARY KEY(scope_id,composition_id,position),UNIQUE(scope_id,source_id,composition_id,position),FOREIGN KEY(scope_id,composition_id) REFERENCES private_composition(scope_id,id),FOREIGN KEY(scope_id,source_id) REFERENCES private_content(scope_id,id)) STRICT" },
		private_schema_table{ "private_content", "CREATE TABLE private_content(scope_id INTEGER NOT NULL REFERENCES review_scope(scope_id),id INTEGER NOT NULL CHECK(id>0),kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 2),owner_id INTEGER NOT NULL CHECK(owner_id>0),sub_id INTEGER NOT NULL CHECK(sub_id>=0),body BLOB NOT NULL CHECK(length(body)<=1048576),digest BLOB NOT NULL CHECK(length(digest)=32),record BLOB NOT NULL CHECK(length(record)<=131072),run_id INTEGER,PRIMARY KEY(scope_id,id),UNIQUE(scope_id,kind,owner_id,sub_id,id),UNIQUE(scope_id,kind,owner_id,id),FOREIGN KEY(scope_id,run_id) REFERENCES private_run(scope_id,id)) STRICT" },
		private_schema_table{ "private_draft", "CREATE TABLE private_draft(scope_id INTEGER NOT NULL REFERENCES review_scope(scope_id),id INTEGER NOT NULL CHECK(id>0),revision INTEGER NOT NULL CHECK(revision>0),record BLOB NOT NULL CHECK(length(record)<=4096),body BLOB CHECK(length(body)<=65536),content_id INTEGER,CHECK((body IS NULL)!=(content_id IS NULL)),PRIMARY KEY(scope_id,id),FOREIGN KEY(scope_id,content_id) REFERENCES private_content(scope_id,id)) STRICT" },
		private_schema_table{ "private_edge", "CREATE TABLE private_edge(scope_id INTEGER NOT NULL,destination_id INTEGER NOT NULL,source_id INTEGER NOT NULL,kind INTEGER NOT NULL CHECK(kind BETWEEN 0 AND 6),CHECK(source_id<destination_id),PRIMARY KEY(scope_id,destination_id,source_id,kind),UNIQUE(scope_id,source_id,destination_id,kind),FOREIGN KEY(scope_id,destination_id) REFERENCES private_content(scope_id,id),FOREIGN KEY(scope_id,source_id) REFERENCES private_content(scope_id,id)) STRICT" },
		private_schema_table{ "private_legacy_note", "CREATE TABLE private_legacy_note(scope_id INTEGER NOT NULL,note_id INTEGER NOT NULL CHECK(note_id>0),thread_id INTEGER NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),PRIMARY KEY(scope_id,note_id),UNIQUE(scope_id,thread_id),FOREIGN KEY(scope_id,thread_id) REFERENCES private_thread(scope_id,id)) STRICT" },
		private_schema_table{ "private_publication", "CREATE TABLE private_publication(scope_id INTEGER NOT NULL,id INTEGER NOT NULL CHECK(id>0),draft_id INTEGER NOT NULL,content_id INTEGER,logical_id TEXT NOT NULL CHECK(length(CAST(logical_id AS BLOB)) BETWEEN 1 AND 1024),server_id TEXT CHECK(length(CAST(server_id AS BLOB)) BETWEEN 1 AND 1024),record BLOB NOT NULL CHECK(length(record)<=8192),PRIMARY KEY(scope_id,id),UNIQUE(scope_id,logical_id),FOREIGN KEY(scope_id,draft_id) REFERENCES private_draft(scope_id,id),FOREIGN KEY(scope_id,content_id) REFERENCES private_content(scope_id,id)) STRICT" },
		private_schema_table{ "private_run", "CREATE TABLE private_run(scope_id INTEGER NOT NULL REFERENCES review_scope(scope_id),id INTEGER NOT NULL CHECK(id>0),record BLOB NOT NULL CHECK(length(record)<=131072),PRIMARY KEY(scope_id,id)) STRICT" },
		private_schema_table{ "private_run_source", "CREATE TABLE private_run_source(scope_id INTEGER NOT NULL,run_id INTEGER NOT NULL,position INTEGER NOT NULL CHECK(position BETWEEN 0 AND 255),source_id INTEGER NOT NULL,PRIMARY KEY(scope_id,run_id,position),UNIQUE(scope_id,source_id,run_id,position),FOREIGN KEY(scope_id,run_id) REFERENCES private_run(scope_id,id),FOREIGN KEY(scope_id,source_id) REFERENCES private_content(scope_id,id)) STRICT" },
		private_schema_table{ "private_scope_state", "CREATE TABLE private_scope_state(scope_id INTEGER PRIMARY KEY REFERENCES review_scope(scope_id),identity_binding BLOB CHECK(length(identity_binding)<=512),last_identity INTEGER NOT NULL DEFAULT 0 CHECK(last_identity>=0),generation INTEGER NOT NULL DEFAULT 1 CHECK(generation>0),note_revision INTEGER NOT NULL DEFAULT 0 CHECK(note_revision>=0),threads INTEGER NOT NULL DEFAULT 0 CHECK(threads BETWEEN 0 AND 4096),revisions INTEGER NOT NULL DEFAULT 0 CHECK(revisions BETWEEN 0 AND 65536),runs INTEGER NOT NULL DEFAULT 0 CHECK(runs BETWEEN 0 AND 65536),findings INTEGER NOT NULL DEFAULT 0 CHECK(findings BETWEEN 0 AND 65536),compositions INTEGER NOT NULL DEFAULT 0 CHECK(compositions BETWEEN 0 AND 4096),candidates INTEGER NOT NULL DEFAULT 0 CHECK(candidates BETWEEN 0 AND 65536),drafts INTEGER NOT NULL DEFAULT 0 CHECK(drafts BETWEEN 0 AND 64),publications INTEGER NOT NULL DEFAULT 0 CHECK(publications BETWEEN 0 AND 65536),thread_bytes INTEGER NOT NULL DEFAULT 0 CHECK(thread_bytes BETWEEN 0 AND 67108864),payload_bytes INTEGER NOT NULL DEFAULT 0 CHECK(payload_bytes BETWEEN 0 AND 67108864)) STRICT" },
		private_schema_table{ "private_store_identity", "CREATE TABLE private_store_identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1),incarnation BLOB NOT NULL CHECK(length(incarnation)=32)) STRICT" },
		private_schema_table{ "private_thread", "CREATE TABLE private_thread(scope_id INTEGER NOT NULL REFERENCES review_scope(scope_id),id INTEGER NOT NULL CHECK(id>0),version INTEGER NOT NULL CHECK(version>0),last_order INTEGER NOT NULL CHECK(last_order>0),lifecycle INTEGER NOT NULL CHECK(lifecycle BETWEEN 0 AND 2),binding BLOB CHECK(length(binding)<=1024),file_identity BLOB,comparison_id BLOB,CHECK((file_identity IS NULL AND comparison_id IS NULL) OR (length(file_identity)=32 AND length(comparison_id)=32)),PRIMARY KEY(scope_id,id)) STRICT" },
		private_schema_table{ "private_turn", "CREATE TABLE private_turn(scope_id INTEGER NOT NULL,id INTEGER NOT NULL CHECK(id>0),thread_id INTEGER NOT NULL,latest_revision INTEGER NOT NULL,PRIMARY KEY(scope_id,id),UNIQUE(scope_id,thread_id,id),FOREIGN KEY(scope_id,thread_id) REFERENCES private_thread(scope_id,id),FOREIGN KEY(scope_id,latest_revision) REFERENCES private_content(scope_id,id) DEFERRABLE INITIALLY DEFERRED) STRICT" }
	};
	/// Schema9 retains completed history separately from the64 active-draft allowance.
	inline constexpr std::string_view PrivateRetainedDraftState = "CREATE TABLE private_scope_state(scope_id INTEGER PRIMARY KEY REFERENCES review_scope(scope_id),identity_binding BLOB CHECK(length(identity_binding)<=512),last_identity INTEGER NOT NULL DEFAULT 0 CHECK(last_identity>=0),generation INTEGER NOT NULL DEFAULT 1 CHECK(generation>0),note_revision INTEGER NOT NULL DEFAULT 0 CHECK(note_revision>=0),threads INTEGER NOT NULL DEFAULT 0 CHECK(threads BETWEEN 0 AND 4096),revisions INTEGER NOT NULL DEFAULT 0 CHECK(revisions BETWEEN 0 AND 65536),runs INTEGER NOT NULL DEFAULT 0 CHECK(runs BETWEEN 0 AND 65536),findings INTEGER NOT NULL DEFAULT 0 CHECK(findings BETWEEN 0 AND 65536),compositions INTEGER NOT NULL DEFAULT 0 CHECK(compositions BETWEEN 0 AND 4096),candidates INTEGER NOT NULL DEFAULT 0 CHECK(candidates BETWEEN 0 AND 65536),drafts INTEGER NOT NULL DEFAULT 0 CHECK(drafts BETWEEN 0 AND 4096),publications INTEGER NOT NULL DEFAULT 0 CHECK(publications BETWEEN 0 AND 65536),thread_bytes INTEGER NOT NULL DEFAULT 0 CHECK(thread_bytes BETWEEN 0 AND 67108864),payload_bytes INTEGER NOT NULL DEFAULT 0 CHECK(payload_bytes BETWEEN 0 AND 67108864)) STRICT";
	/// \brief [[BPR-1210]]. A file note's path when it was written (schema 8).
	///
	/// \details One row per note thread that has a path; no row is the null
	/// path of a note written before schema 8, or of a whole-review note. A
	/// side table rather than a column on `private_thread`, so the migration
	/// creates one table instead of rebuilding a table other tables reference.
	inline constexpr private_schema_table PrivateNotePathTable{ "private_note_path", "CREATE TABLE private_note_path(scope_id INTEGER NOT NULL,thread_id INTEGER NOT NULL,path TEXT NOT NULL CHECK(length(CAST(path AS BLOB)) BETWEEN 1 AND 4096),PRIMARY KEY(scope_id,thread_id),FOREIGN KEY(scope_id,thread_id) REFERENCES private_thread(scope_id,id)) STRICT" };
	/// \brief [[BPR-1591]]. A note's line (schema 10): its side, zero-based
	/// line and the blob that side showed when it was written.
	///
	/// \details One row per note thread written on a line; no row is a note
	/// on the whole file or the pull request, or one written before schema 10.
	/// A side table, as the path is, so the migration creates one table.
	inline constexpr private_schema_table PrivateNoteLineTable{ "private_note_line", "CREATE TABLE private_note_line(scope_id INTEGER NOT NULL,thread_id INTEGER NOT NULL,side INTEGER NOT NULL CHECK(side IN(0,1)),line INTEGER NOT NULL CHECK(line BETWEEN 0 AND 4294967295),blob BLOB CHECK(blob IS NULL OR length(blob) IN(20,32)),PRIMARY KEY(scope_id,thread_id),FOREIGN KEY(scope_id,thread_id) REFERENCES private_thread(scope_id,id)) STRICT" };
	/// \brief Called within the ledger's existing all-version migration transaction.
	[[nodiscard]] auto migrate_private_review(::sqlite3*) -> std::expected<void, failure>;
	/// \brief [[BPR-1210]]. Schema 7 to 8: the note path table, empty.
	[[nodiscard]] auto migrate_private_note_paths(::sqlite3*) -> std::expected<void, failure>;
	/// \brief [[BPR-1591]]. Schema 9 to 10: the note line table, empty.
	[[nodiscard]] auto migrate_private_note_lines(::sqlite3*) -> std::expected<void, failure>;
	[[nodiscard]] auto private_store_note(::sqlite3*, std::int64_t, const application::local_note_record&, std::optional<application::local_note_revision>) -> std::expected<application::local_note_record, application::local_note_failure>;
	[[nodiscard]] auto private_erase_note(::sqlite3*, std::int64_t, application::local_note_id, application::local_note_revision) -> std::expected<void, application::local_note_failure>;
	[[nodiscard]] auto private_load_notes(::sqlite3*, std::int64_t) -> std::expected<std::vector<application::local_note_record>, failure>;
}
#endif
